package com.pavithran.aichat.service; import com.openai.client.OpenAIClient; import com.openai.models.ChatModel; import com.openai.models.responses.ResponseCreateParams; import com.pavithran.aichat.dto.*; import com.pavithran.aichat.model.*; import com.pavithran.aichat.repo.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID; @Service public class ChatService { private static final String SYSTEM="You are Pavi AI, a helpful, friendly assistant. Be accurate, practical and concise. If you are unsure, say so rather than inventing facts."; private final OpenAIClient openAI; private final ConversationRepository conversations; private final MessageRepository messages; public ChatService(OpenAIClient o,ConversationRepository c,MessageRepository m){openAI=o;conversations=c;messages=m;} @Transactional public ChatResponse chat(ChatRequest req){String device=req.deviceId().trim(); Conversation c; if(req.conversationId()==null){c=new Conversation();c.setDeviceId(device);String t=req.message().trim();c.setTitle(t.length()>48?t.substring(0,48)+"…":t);c=conversations.save(c);}else c=conversations.findByIdAndDeviceId(req.conversationId(),device).orElseThrow(()->new IllegalArgumentException("Conversation not found")); save(c.getId(),"user",req.message()); StringBuilder p=new StringBuilder(SYSTEM).append("\n\nConversation:\n"); messages.findByConversationIdOrderByCreatedAtAsc(c.getId()).forEach(m->p.append(m.getRole()).append(": ").append(m.getContent()).append("\n")); ResponseCreateParams params=ResponseCreateParams.builder().input(p.toString()).model(ChatModel.GPT_5_2).build(); var response=openAI.responses().create(params); String reply=response.outputText().orElse("I couldn't generate a response right now."); save(c.getId(),"assistant",reply);c.touch();conversations.save(c);return new ChatResponse(c.getId(),reply);} private void save(UUID id,String role,String content){Message m=new Message();m.setConversationId(id);m.setRole(role);m.setContent(content);messages.save(m);} }
